style.css:
@-moz-document url-prefix("https://educamosclm.castillalamancha.es/s/home") {
html, body { background: #ffffff !important; color: #69515d !important; }
h1, h2, h3 { font-family: Georgia, serif !important; color: #69515d !important; }
a { color: #985b75 !important; }
header, nav { background-color: transparent !important; border-color: #ead6de !important; }
img.image-desktop[src$="desktopGenerico.svg"] {
content: url("data:image/jpeg;base64,") !important;
width: 100% !important;
max-width: 1080px !important;
height: auto !important;
display: block !important;
margin: 12px auto !important;
object-fit: contain !important;
object-position: center !important;
border-radius: 16px !important;
}
.mat-drawer-inner-container {
background-color: #fffdfc !important;
background-image: url("data:image/jpeg;base64,") !important;
background-position: center top !important;
background-size: 100% auto !important;
background-repeat: repeat-y !important;
}
.sidebar-container, .menu-container, #menu-lateral, .menu-perfil, .menu-principal {
background-color: transparent !important;
}
#menu-lateral button.menu-item, #cambio-vista, #centro-access {
background-color: rgba(255,255,255,0.85) !important;
color: #69515d !important;
border-radius: 9px !important;
}
#menu-lateral button.menu-item.current-route, #menu-lateral button.menu-item:hover {
background-color: #efdce4 !important;
}
.sidebar-container .items-style, .sidebar-container .mdc-list-item__primary-text { color: #69515d !important; }
.sidebar-container i, .sidebar-container .primary { color: #985b75 !important; }
.sidebar-container svg.primary path { fill: #985b75 !important; }
.sidebar-container .iconoNaranja { background-color: #efdce4 !important; }
.sidebar-container .mat-divider { border-color: #ead6de !important; }
button { color: #985b75 !important; }
input, select, textarea { color: #985b75 !important; }
::selection { background: #efd6e0; color: #594650; }
img.logo-educamos { filter: grayscale(1) sepia(.25) !important; }
#menu-lateral button.menu-item.current-route { border-color: #d8b2c0 !important; }
h2.img-title {
position: absolute !important;
width: 1px !important;
height: 1px !important;
padding: 0 !important;
margin: -1px !important;
overflow: hidden !important;
clip: rect(0,0,0,0) !important;
white-space: nowrap !important;
border: 0 !important;
}
h2.img-title::before, h2.img-title::after {
content: none !important;
background: transparent !important;
}
.row.start-xs.start-sm.start-lg[style*="max-width: 100%"] {
background-color: #fff8fa !important;
border-top: 1px solid #ead6de !important;
margin: 0 !important;
padding: 20px 0 16px !important;
box-sizing: border-box !important;
width: 100% !important;
color: #69515d !important;
}
.padding-options { background: transparent !important; color: #69515d !important; }
.padding-options mat-label p { color: #69515d !important; font-size: 13px !important; line-height: 1.5 !important; }
.padding-options mat-label.title p { font-family: Georgia, serif !important; font-size: 17px !important; color: #985b75 !important; }
.padding-options a, .padding-options i { color: #985b75 !important; }
.container-fluid.parent-container.container-mobile { width: 100% !important; max-width: none !important; box-sizing: border-box !important; padding: 12px 20px !important; }
.parent-container .image-box { width: 100% !important; max-width: none !important; height: auto !important; min-height: 0 !important; margin: 0 auto !important; background: white !important; box-shadow: none !important; overflow: visible !important; }
.parent-container img.image-desktop[src$="desktopGenerico.svg"] { width: 100% !important; max-width: none !important; height: auto !important; margin: 0 auto !important; display: block !important; }
.parent-container img.image-mobile { display: none !important; }
.parent-container .expanded-overlay, .parent-container .overlay-text-mobile { background: transparent !important; pointer-events: none !important; }
.parent-container .img-title-mobile { position: absolute !important; width: 1px !important; height: 1px !important; overflow: hidden !important; clip: rect(0,0,0,0) !important; }
@media (min-width: 1100px) {
.container-fluid.parent-container.container-mobile {
width: 76vw !important;
max-width: none !important;
margin-left: 0 !important;
margin-right: 0 !important;
padding-left: 20px !important;
padding-right: 20px !important;
}
.parent-container.container-mobile > .row {
width: 100% !important;
max-width: none !important;
margin: 0 !important;
}
.parent-container.container-mobile > .row > .col-lg-12 {
width: 100% !important;
max-width: 100% !important;
flex: 0 0 100% !important;
padding: 0 !important;
}
}
:root { --my-icon: #a46b82; --my-icon-bg: #f8eef2; }
#catalog-button, #message-button, #suport-button, #accessmodule-button,
#profile-access, .ri-layout-3-line, #profile-access .name {
color: var(--my-icon) !important;
}
#catalog-button i, #message-button i, #suport-button i, #accessmodule-button i,
#profile-access i, .ri-layout-3-line::before {
color: var(--my-icon) !important;
}
#catalog-button:hover, #message-button:hover, #suport-button:hover, #accessmodule-button:hover {
background-color: var(--my-icon-bg) !important;
}
#profile-access .image-container { background: #f8eef2 !important; border-color: #d8b2c0 !important; }
#profile-access img.imagen-usuario {
content: url("data:image/jpeg;base64,") !important;
object-fit: cover !important; border-radius: 50% !important; width: 100% !important; height: 100% !important;
}
#profile-access .ri-graduation-cap-line { display: none !important; }
#message-button .badge { background-color: #d9b2c3 !important; color: #573846 !important; }
}
